& > :is(menu, menuitem) {
  appearance: none;
  margin: var(--menu-item-margin);
  min-block-size: 24px;
  padding-inline: 8px;
  padding-block: var(--menu-item-padding);
  border-radius: 3px;
  background-color: transparent;

  &:focus {
    outline: 0;
  }

  &[checked],
  &[selected] {
    --menuitem-icon: var(--icon-check);
    -moz-context-properties: fill, stroke;
    stroke: currentColor;
    color: inherit;
  }

  &:not([disabled], :active)[_moz-menuactive] {
    color: inherit;
    background-color: var(--panel-background-color-dimmed);
  }

  &:not([disabled])[_moz-menuactive]:active {
    color: inherit;
    background-color: var(--panel-background-color-dimmed-further);
    box-shadow: 0 1px 0 hsla(210, 4%, 10%, 0.03) inset;
  }

